#!/usr/bin/env bash

# Upload the source distributions in the "sdists" directory (as
# generated by mkSDists.sh) to Hackage.
#
# USAGE: ./upload.sh [--publish]
#
# By default the packages are uploaded as candidates. Pass --publish
# to publish them directly. Each source distribution is deleted once
# it has been successfully uploaded (or if Hackage reports that it
# was already published), so re-running the script after a failure
# only retries the remaining ones.
#
# Set HACKAGE_TOKEN to authenticate with a Hackage token, otherwise
# the credentials in the cabal configuration are used.

set -uo pipefail

BINDINGS_DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null 2>&1 && pwd )"
SDIST_DIR="$BINDINGS_DIR/sdists"

UPLOAD_FLAGS=()
case "${1:-}" in
    --publish)
        UPLOAD_FLAGS+=(--publish)
        ;;
    "")
        ;;
    *)
        echo "USAGE: $0 [--publish]" >&2
        exit 1
        ;;
esac

if [ -n "${HACKAGE_TOKEN:-}" ]; then
    UPLOAD_FLAGS+=(--token="$HACKAGE_TOKEN")
fi

shopt -s nullglob
SDISTS=("$SDIST_DIR"/*.tar.gz)

if [ ${#SDISTS[@]} -eq 0 ]; then
    echo "Error: no source distributions found in $SDIST_DIR, run mkSDists.sh first." >&2
    exit 1
fi

for sdist in "${SDISTS[@]}"; do
    echo -n "Uploading $(basename "$sdist")... "
    result=$(cabal upload "${UPLOAD_FLAGS[@]}" "$sdist" 2>&1)
    status=$?
    if echo "$result" | grep -q "already been uploaded"; then
        echo "already uploaded, skipping"
        rm "$sdist"
    elif [ $status -eq 0 ]; then
        echo "OK"
        rm "$sdist"
    else
        echo "FAILED"
        echo "$result" >&2
        exit 1
    fi
done
